"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import {
  DocumentArrowDownIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/outline';
import { useAction } from "next-safe-action/hooks";

/**
 * Reusable Export Button Component with green styling
 * Same design as Guidelines Repository export button
 *
 * @example Basic usage
 * <ExportButton
 *   action={exportDocumentReportsToExcel}
 *   params={{ dateRange, sourceName }}
 *   label="Export to Excel"
 * />
 *
 * @example With custom handlers
 * <ExportButton
 *   action={exportUserMetrics}
 *   params={{ dateRange }}
 *   onSuccess={(result) => console.log('Success!')}
 *   disabled={isLoading}
 * />
 */

// Type for export action response
type ExportActionResult = {
  data?: {
    file?: string;
    fileBase64?: string;
    filename?: string;
    fileName?: string;
  } | string;
};

interface ExportButtonProps<TParams extends Record<string, unknown>> {
  /** The server action to execute for export */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  action: any;

  /** Parameters to pass to the action */
  params: TParams;

  /** Button label (default: "Export to Excel") */
  label?: string;

  /** Disabled state */
  disabled?: boolean;

  /** Custom success handler */
  onSuccess?: (result: ExportActionResult) => void;

  /** Custom error handler */
  onError?: (error: unknown) => void;

  /** Additional button classes */
  className?: string;
}

export function ExportButton<TParams extends Record<string, unknown>>({
  action,
  params,
  label = "Export to Excel",
  disabled = false,
  onSuccess,
  onError,
  className = "",
}: ExportButtonProps<TParams>) {
  const [isExporting, setIsExporting] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [showError, setShowError] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string>("");

  const { execute: exportAction, isExecuting } = useAction(action, {
    onSuccess: (result: ExportActionResult) => {
      try {
        //console.log('[ExportButton] onSuccess called with result:', result);

        // Extract file data from common response patterns
        // Pattern 1: { data: { file, filename } }
        // Pattern 2: { data: "base64string" }
        let fileData: string | undefined;
        let fileName = 'export.xlsx';

        if (typeof result?.data === 'string') {
          // Pattern 2: data is directly a base64 string
          //console.log('[ExportButton] Pattern 2: data is string, length:', result.data.length);
          fileData = result.data;
        } else if (result?.data && typeof result.data === 'object') {
          // Pattern 1: data is an object with file and filename properties
          //console.log('[ExportButton] Pattern 1: data is object');
          fileData = result.data.file || result.data.fileBase64;
          fileName = result.data.filename || result.data.fileName || 'export.xlsx';
          //console.log('[ExportButton] Extracted fileData length:', fileData?.length, 'fileName:', fileName);
        }

        if (fileData) {
          //console.log('[ExportButton] Processing fileData, length:', fileData.length);
          // Convert base64 to blob and create download link
          const byteCharacters = atob(fileData);
          const byteNumbers = new Array(byteCharacters.length);
          for (let i = 0; i < byteCharacters.length; i++) {
            byteNumbers[i] = byteCharacters.charCodeAt(i);
          }
          const byteArray = new Uint8Array(byteNumbers);

          // Determine MIME type based on file extension
          const mimeType = fileName?.endsWith('.csv')
            ? 'text/csv'
            : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

          const blob = new Blob([byteArray], { type: mimeType });

          // Create download link
          const url = window.URL.createObjectURL(blob);
          const link = document.createElement('a');
          link.href = url;
          link.download = fileName || 'export.xlsx';
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          window.URL.revokeObjectURL(url);

          // Show success state briefly
          setShowSuccess(true);
          setTimeout(() => setShowSuccess(false), 2000);

          //console.log('[ExportButton] Download triggered successfully');

          // Call custom success handler if provided
          onSuccess?.(result);
        } else {
          console.error('[ExportButton] No fileData found in result!');
          console.error('[ExportButton] result?.data:', result?.data);
        }
      } catch (error) {
        console.error('[ExportButton] Export processing error:', error);
        if (process.env.NODE_ENV === 'development') {
          console.error('[ExportButton] Full error details:', error);
        }
        setErrorMessage("Failed to process export data");
        setShowError(true);
        setTimeout(() => {
          setShowError(false);
          setErrorMessage("");
        }, 5000);
      } finally {
        setIsExporting(false);
      }
    },
    onError: (error: unknown) => {
      console.error('[ExportButton] onError called with error:', error);
      // Log error in development only
      if (process.env.NODE_ENV === 'development') {
        console.error('[ExportButton] Export failed (dev mode):', error);
      }

      // Determine user-friendly error message
      let userMessage = "Export failed. Please try again.";

      try {
        // Type guard for error object
        const isErrorObject = (obj: unknown): obj is Record<string, unknown> => {
          return typeof obj === 'object' && obj !== null;
        };

        if (isErrorObject(error)) {
          if ((error.error as Record<string, unknown>)?.serverError) {
            userMessage = "Server error occurred during export.";
          } else if ((error.error as Record<string, unknown>)?.validationErrors) {
            userMessage = "Invalid data detected. Please check your selection.";
          } else if (error.error && typeof error.error === 'string') {
            // Handle string error messages
            const errorStr = error.error.toLowerCase();
            if (errorStr.includes('network')) {
              userMessage = "Network error. Please check your connection.";
            } else if (errorStr.includes('permission')) {
              userMessage = "You don't have permission to export.";
            } else if (errorStr.includes('not found')) {
              userMessage = "Data not found. Please refresh and try again.";
            }
          } else if (error.serverError) {
            userMessage = "Server error occurred during export.";
          } else if (error.validationErrors) {
            userMessage = "Invalid data detected. Please check your selection.";
          }
        }
      } catch (parseError) {
        if (process.env.NODE_ENV === 'development') {
          console.error('Error parsing export error:', parseError);
        }
        userMessage = "Export failed. Please try again.";
      }

      setErrorMessage(userMessage);
      setShowError(true);

      // Auto-hide error after 5 seconds
      setTimeout(() => {
        setShowError(false);
        setErrorMessage("");
      }, 5000);

      setIsExporting(false);

      // Call custom error handler if provided
      onError?.(error);
    }
  });

  const handleExport = async () => {
    //console.log('[ExportButton] handleExport called with params:', params);

    if (disabled || isLoading) {
      //console.log('[ExportButton] Export blocked - disabled or isLoading');
      return;
    }

    // Clear any previous states
    setShowError(false);
    setShowSuccess(false);
    setErrorMessage("");
    setIsExporting(true);

    try {
      //console.log('[ExportButton] Calling exportAction...');
      await exportAction(params);
      //console.log('[ExportButton] exportAction completed');
    } catch (error) {
      //console.error('[ExportButton] Caught error in handleExport:', error);
      if (process.env.NODE_ENV === 'development') {
        console.error('[ExportButton] Export error (dev mode):', error);
      }

      // Set error state for user feedback
      setErrorMessage("An unexpected error occurred during export.");
      setShowError(true);

      // Auto-hide error after 5 seconds
      setTimeout(() => {
        setShowError(false);
        setErrorMessage("");
      }, 5000);

      setIsExporting(false);
    }
  };

  const isLoading = isExporting || isExecuting;

  return (
    <div className="relative">
      <Button
        onClick={handleExport}
        disabled={disabled || isLoading}
        size="sm"
        className={`text-white shadow-md hover:shadow-lg transition-all duration-200 ${showError
            ? 'bg-red-600 hover:bg-red-700'
            : showSuccess
              ? 'bg-green-600 hover:bg-green-700'
              : 'bg-emerald-600 hover:bg-emerald-700'
          } ${className}`}
        title={showError ? errorMessage : label}
      >
        {isLoading ? (
          <>
            <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
            Exporting...
          </>
        ) : showError ? (
          <>
            <ExclamationTriangleIcon className="h-4 w-4 mr-2" />
            Export Failed
          </>
        ) : showSuccess ? (
          <>
            <CheckCircleIcon className="h-4 w-4 mr-2" />
            Exported!
          </>
        ) : (
          <>
            <DocumentArrowDownIcon className="h-4 w-4 mr-2" />
            {label}
          </>
        )}
      </Button>

      {/* Error Message Tooltip */}
      {showError && errorMessage && (
        <div className="absolute top-full right-0 mt-2 w-64 p-3 bg-red-50 border border-red-200 rounded-md shadow-lg z-50">
          <div className="flex items-start gap-2">
            <ExclamationTriangleIcon className="h-4 w-4 text-red-500 mt-0.5 flex-shrink-0" />
            <div>
              <p className="text-sm font-medium text-red-800">Export Error</p>
              <p className="text-xs text-red-600 mt-1">{errorMessage}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
